-- Evidência do credenciamento da Worknet (o sistema de bip na entrada do Summit
-- 2026), a partir do relatório da Worknet de 23/09/2026 (relatorio-mind-completo.xlsx).
--
-- O relatório traz UMA data de check-in por crachá: a retirada do crachá. Quem veio
-- nos dois dias aparece só no primeiro (por isso 17/09 tem poucas linhas). Uma linha
-- aqui = o ingresso foi bipado naquele dia. por_email = check-in manual que a Worknet
-- registrou sem número de ingresso; casa pelo e-mail.
-- Os 93 crachás retirados de 13 a 15/09 (credenciamento antecipado), os 917 de
-- staff e os 42 de palestrantes não entram: não marcam dia ou não são ingresso.
-- Idempotente.
create table if not exists credenciamento_summit_2026.credenciamento_worknet (
  chave     text    not null,             -- número do ingresso (maiúsculo) ou e-mail (minúsculo)
  dia       int     not null,             -- 16 ou 17 (setembro de 2026)
  por_email boolean not null default false,
  primary key (chave, dia, por_email)
);
comment on table credenciamento_summit_2026.credenciamento_worknet is
  'Evidência do credenciamento da Worknet (o sistema de bip na entrada), relatório de 23/09/2026: uma linha por ingresso e dia (16 ou 17/09) em que o ingresso foi bipado. por_email = check-in manual que veio sem número de ingresso, casado pelo e-mail. Os 93 crachás retirados de 13 a 15/09 (credenciamento antecipado) não marcam dia.';

-- 1.857 por ingresso (1.670 em 16/09, 187 em 17/09) + 9 por e-mail (4 + 5).
on conflict (chave, dia, por_email) do nothing;
